import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> numeros = Arrays.asList(5, 12, 8, 15, 3, 20, 7, 25, 11);

        int suma = numeros.stream()
            .filter(n -> n > 10)
            .mapToInt(Integer::intValue)
            .sum();

        System.out.println("Sum of numbers greater than 10: " + suma);
    }
}

