import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<String> lineas = Arrays.asList(
            "public class Main",
            "System.out.println(\"Java es genial\");",
            "int x = 5;",
            "// Esto es Java",
            "return true;",
            "import java.util.*;",
            "String java = \"lenguaje\";",
            "for (int i = 0; i < 10; i++)"
        );

        long cantidad = lineas.stream()
            .filter(l -> l.toLowerCase().contains("java"))
            .peek(l -> System.out.println(l.toUpperCase()))
            .count();

        System.out.println("Lines that mention Java: " + cantidad);
    }
}

