import java.util.*;
import java.util.stream.*;

record Persona(String nombre, int edad, String ciudad) {}

public class Main {
    public static void main(String[] args) {
        List<Persona> personas = Arrays.asList(
            new Persona("Ana", 25, "Lima"),
            new Persona("Luis", 30, "Lima"),
            new Persona("Maria", 22, "Cusco"),
            new Persona("Pedro", 35, "Cusco"),
            new Persona("Sofia", 28, "Lima"),
            new Persona("Carlos", 40, "Arequipa"),
            new Persona("Elena", 32, "Cusco"),
            new Persona("Miguel", 27, "Arequipa")
        );

        Map<String, Double> promedios = personas.stream()
            .collect(Collectors.groupingBy(
                Persona::ciudad,
                Collectors.averagingInt(Persona::edad)
            ));

        promedios.forEach((ciudad, promedio) ->
            System.out.println(ciudad + ": " + promedio)
        );
    }
}
